            new[] { "Ignored: no more notices about this folder.", "تم التجاهل: لا مزيد من الإشعارات عن هذا المجلد.", "Игнорируется: больше никаких уведомлений об этой папке.", "Ignorada: no más avisos sobre esta carpeta." },
            new[] { "The size to go back down to must be smaller than the limit.", "يجب أن يكون الحجم الذي يُنزل إليه أصغر من الحد.", "Размер, до которого уменьшать, должен быть меньше предела.", "El tamaño al que bajar debe ser menor que el límite." },
            new[] { "Not saved:", "لم يُحفظ:", "Не сохранено:", "No guardado:" },
            new[] { "Right now it's under the limit: nothing is deleted today.", "هو الآن تحت الحد: لا يُحذف شيء اليوم.", "Сейчас она меньше предела: сегодня ничего не удаляется.", "Ahora está por debajo del límite: hoy no se borra nada." },
            new[] { "Programs are never deleted. The first two times they go to Undo (Tools > Undo puts them back), then they're deleted. Change it here any time.", "لا تُحذف البرامج أبدًا. في أول مرتين تذهب الملفات إلى التراجع (الأدوات > التراجع يعيدها)، ثم تُحذف. يمكنك تغيير ذلك هنا في أي وقت.", "Программы не удаляются никогда. Первые два раза файлы попадают в «Отмену» (Инструменты > Отмена возвращает их), потом удаляются. Это можно изменить здесь в любой момент.", "Los programas nunca se borran. Las dos primeras veces los archivos van a Deshacer (Herramientas > Deshacer los devuelve); después se borran. Puedes cambiarlo aquí cuando quieras." },
            new[] { "Nothing to delete today.", "لا شيء للحذف اليوم.", "Сегодня удалять нечего.", "Hoy no hay nada que borrar." },
            new[] { "Elixar can't tell for sure what this is. Open it and look before you choose what to do.", "لا يستطيع Elixar أن يعرف بالتأكيد ما هذا. افتحه وانظر قبل أن تختار ما تفعله.", "Elixar не может точно сказать, что это. Откройте и посмотрите, прежде чем выбирать.", "Elixar no sabe con seguridad qué es. Ábrela y mira antes de elegir qué hacer." },
            new[] { "SecureAPlus's uploads to SecureAge are stuck: it keeps making new ones and never removes the old ones. Update or repair SecureAPlus. Deleting old ones doesn't turn off your protection.", "عمليات رفع SecureAPlus إلى SecureAge عالقة: يواصل إنشاء ملفات جديدة ولا يحذف القديمة. حدّث SecureAPlus أو أصلحه. حذف القديمة لا يوقف حمايتك.", "Загрузки SecureAPlus в SecureAge застряли: он создаёт новые и не удаляет старые. Обновите или восстановите SecureAPlus. Удаление старых не отключает защиту.", "Las subidas de SecureAPlus a SecureAge están atascadas: crea nuevas y nunca borra las antiguas. Actualiza o repara SecureAPlus. Borrar las antiguas no desactiva tu protección." },
            new[] { "SecureAPlus (an antivirus, by SecureAge Technology)", "SecureAPlus (مضاد فيروسات من SecureAge Technology)", "SecureAPlus (антивирус от SecureAge Technology)", "SecureAPlus (un antivirus de SecureAge Technology)" },
            new[] { "Your company sets these rules in Policy manager.", "تضع شركتك هذه القواعد في مدير السياسات.", "Эти правила задаёт ваша компания в диспетчере политик.", "Tu empresa fija estas reglas en el Administrador de directivas." },
            new[] { "This folder looks unusual: scan it with Microsoft Defender first.", "هذا المجلد يبدو غير عادي: افحصه أولًا باستخدام Microsoft Defender.", "Эта папка выглядит необычно: сначала проверьте её Microsoft Defender.", "Esta carpeta parece inusual: analízala primero con Microsoft Defender." },
            new[] { "Windows' own folder: Elixar doesn't delete here.", "مجلد خاص بـ Windows: لا يحذف Elixar هنا.", "Собственная папка Windows: Elixar здесь не удаляет.", "Carpeta propia de Windows: Elixar no borra aquí." },
            new[] { "Your own files: Elixar never deletes them on a timer.", "ملفاتك الخاصة: لا يحذفها Elixar أبدًا وفق جدول.", "Ваши собственные файлы: Elixar никогда не удаляет их по расписанию.", "Tus propios archivos: Elixar nunca los borra según un horario." },
            new[] { "Elixar only deletes on a schedule in an app's folder (in ProgramData or AppData).", "لا يحذف Elixar وفق جدول إلا في مجلد تطبيق (في ProgramData أو AppData).", "Elixar удаляет по расписанию только в папке приложения (в ProgramData или AppData).", "Elixar solo borra según un horario en la carpeta de una aplicación (en ProgramData o AppData)." },
            new[] { "This is Elixar's own folder.", "هذا مجلد Elixar نفسه.", "Это папка самого Elixar.", "Esta es la carpeta de Elixar." },
            new[] { "Not possible here.", "غير ممكن هنا.", "Здесь невозможно.", "No es posible aquí." },
            new[] { "Sounds", "الأصوات", "Звуки", "Sonidos" },
            new[] { "Elixar's own (Potion)", "أصوات Elixar (الجرعة)", "Собственные Elixar («Зелье»)", "Propios de Elixar (Poción)" },
            new[] { "Windows' own sounds", "أصوات Windows", "Звуки Windows", "Sonidos de Windows" },
